// Source of truth for costclaw SocialClip copy in the product-owned props workspace.
// files are GENERATED by this script; edit copy here, never in the JSON files
// (they get clobbered). Copy is sourced verbatim from
// The product-owned brief.json supplies its `social` block and `features`/`cta`.
//
// Usage: node scripts/build-costclaw-social-props.mjs
import {mkdirSync, readFileSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';
import {projectArg, resolveWorkspace} from './lib/workspace.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const argv = process.argv.slice(2);
const workspace = resolveWorkspace(root, {brand: 'costclaw', project: projectArg(argv)});
const brief = JSON.parse(readFileSync(join(workspace.marketingDir, 'brief.json'), 'utf8'));

// The "leak, priced" feature is the recoverable-spend payoff (feature-leak.png
// shows the headline stat), so both platform cuts pair it with that screenshot
// and its benefit lines -- the hook line leads them into the specific bullets.
const leakFeature = brief.features.find((f) => f.key === 'recoverable-spend');

const PLATFORMS = {
  x: {
    kicker: 'costclaw.io',
    headline: brief.social.x.headline,
    hook: brief.social.x.hook,
  },
  linkedin: {
    kicker: 'costclaw.io',
    headline: brief.social.linkedin.headline,
    hook: brief.social.linkedin.hook,
  },
};

for (const [platform, copy] of Object.entries(PLATFORMS)) {
  const props = {
    brandId: 'costclaw',
    kicker: copy.kicker,
    headline: copy.headline,
    lines: [copy.hook, ...leakFeature.benefitLines],
    screenshot: 'costclaw/feature-leak.png',
    cta: brief.cta,
    command: 'npx costclaw audit',
    video: 'costclaw/demo.webm',
  };
  const outPath = join(workspace.propsDir, `costclaw-social-${platform}.json`);
  mkdirSync(dirname(outPath), {recursive: true});
  writeFileSync(outPath, JSON.stringify(props, null, 2) + '\n');
  console.log(`wrote ${outPath}`);
}
